arguments.file_text:
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker(reorderThreshold: 5);

    // ── Stock level ──────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    public void AddStock_SingleAdd_IncreasesLevel()
    {
        _tracker.AddStock("SKU-A", 20);
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_MultipleCalls_Accumulates()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 7);
        Assert.AreEqual(17, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ReducesLevel()
    {
        _tracker.AddStock("SKU-A", 20);
        _tracker.RemoveStock("SKU-A", 8);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExactAmount_LeavesZero()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.RemoveStock("SKU-A", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExceedsLevel_Throws()
    {
        _tracker.AddStock("SKU-A", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 10));
    }

    [TestMethod]
    public void RemoveStock_FromUnknownSku_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("GHOST", 1));
    }

    // ── Argument validation ──────────────────────────────────

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", -5));
    }

    [TestMethod]
    public void RemoveStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-A", 0));
    }

    [TestMethod]
    public void Constructor_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => new InventoryTracker(reorderThreshold: -1));
    }

    // ── Reorder alerts ───────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 3); // threshold is 5
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 20);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("UNKNOWN"));
    }

    [TestMethod]
    public void NeedsReorder_AfterRemoval_ReflectsNewLevel()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));

        _tracker.RemoveStock("SKU-A", 6);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    // ── Warehouse assignment ─────────────────────────────────

    [TestMethod]
    public void GetWarehouse_Unassigned_ReturnsNull()
    {
        Assert.IsNull(_tracker.GetWarehouse("SKU-A"));
    }

    [TestMethod]
    public void AssignWarehouse_ThenGet_ReturnsWarehouseId()
    {
        _tracker.AssignWarehouse("SKU-A", "WH-EAST");
        Assert.AreEqual("WH-EAST", _tracker.GetWarehouse("SKU-A"));
    }

    [TestMethod]
    public void AssignWarehouse_Reassign_UpdatesWarehouse()
    {
        _tracker.AssignWarehouse("SKU-A", "WH-EAST");
        _tracker.AssignWarehouse("SKU-A", "WH-WEST");
        Assert.AreEqual("WH-WEST", _tracker.GetWarehouse("SKU-A"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void AssignWarehouse_InvalidWarehouseId_Throws(string? whId)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AssignWarehouse("SKU-A", whId!));
    }

    // ── Warehouse transfers ──────────────────────────────────

    [TestMethod]
    public void TransferStock_MovesQuantityBetweenTrackers()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 30);

        _tracker.TransferStock("SKU-A", 12, destination);

        Assert.AreEqual(18, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(12, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferStock_EntireStock_LeavesZeroAtSource()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 10);

        _tracker.TransferStock("SKU-A", 10, destination);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(10, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferStock_ExceedsSource_Throws()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 5);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-A", 20, destination));
    }

    [TestMethod]
    public void TransferStock_NullDestination_Throws()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-A", 5, null!));
    }

    [TestMethod]
    public void TransferStock_FailedTransfer_DoesNotAlterSource()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 5);

        try { _tracker.TransferStock("SKU-A", 20, destination); }
        catch (InvalidOperationException) { }

        Assert.AreEqual(5, _tracker.GetStockLevel("SKU-A"));
